#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
从 Sorftime category_report 响应中提取统计数据
处理大数据文件 (>25000 tokens) 的标准工具
"""

import re
import sys
import json
from typing import Dict, Optional


def extract_statistics(file_path: str) -> Dict[str, str]:
    """
    从 Sorftime 响应文件中提取类目统计数据

    Args:
        file_path: Sorftime API 响应文件路径

    Returns:
        包含统计数据的字典
    """
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            content = f.read()
    except FileNotFoundError:
        print(f"错误: 文件不存在 {file_path}")
        return {}
    except Exception as e:
        print(f"错误: 读取文件失败 - {e}")
        return {}

    # 定义需要提取的字段模式
    patterns = {
        '总销量': r'"top100产品月销量":"?(\d+)"?',
        '总销额': r'"top100产品月销额":"?([\d.]+)"?',
        '平均价格': r'"average_price":"?([\d.]+)"?',
        '中位数价格': r'"median_price":"?([\d.]+)"?',
        'Top3品牌占比': r'"top3_brands_sales_volume_share":"?([\d.]+%?)"?',
        'Amazon自营占比': r'"amazonOwned_sales_volume_share":"?([\d.]+%?)"?',
        '高评分占比': r'"high_rated_sales_volume_share":"?([\d.]+%?)"?',
        '低评论占比': r'"low_reviews_sales_volume_share":"?([\d.]+%?)"?',
    }

    results = {}
    for name, pattern in patterns.items():
        match = re.search(pattern, content)
        if match:
            results[name] = match.group(1)
        else:
            results[name] = "未找到"

    return results


def calculate_scores_from_stats(stats: Dict[str, str]) -> Dict[str, float]:
    """
    基于统计数据计算五维评分

    Args:
        stats: 从 extract_statistics 返回的统计数据

    Returns:
        五维评分字典
    """
    # 辅助函数：安全提取数值
    def safe_float(value, default=0):
        try:
            return float(str(value).replace('%', '').replace(',', ''))
        except:
            return default

    # 提取数值
    revenue = safe_float(stats.get('总销额', 0))
    top3_share = safe_float(stats.get('Top3品牌占比', 0))
    amazon_share = safe_float(stats.get('Amazon自营占比', 0))
    low_review_share = safe_float(stats.get('低评论占比', 0))
    avg_price = safe_float(stats.get('平均价格', 0))

    scores = {}

    # 1. 市场规模 (20分)
    if revenue > 10000000:
        scores['市场规模'] = 20
    elif revenue > 5000000:
        scores['市场规模'] = 17
    elif revenue > 1000000:
        scores['市场规模'] = 14
    else:
        scores['市场规模'] = 10

    # 2. 增长潜力 (25分) - 基于低评论产品占比 (新品机会)
    if low_review_share > 40:
        scores['增长潜力'] = 22
    elif low_review_share > 20:
        scores['增长潜力'] = 18
    else:
        scores['增长潜力'] = 14

    # 3. 竞争烈度 (20分) - 基于 Top3 品牌占比
    if top3_share < 30:
        scores['竞争烈度'] = 18  # 低度集中
    elif top3_share < 50:
        scores['竞争烈度'] = 14  # 中度集中
    else:
        scores['竞争烈度'] = 8   # 高度集中

    # 4. 进入壁垒 (20分)
    barrier_score = 0

    # Amazon 占比越低，壁垒越小
    if amazon_share < 20:
        barrier_score += 10
    elif amazon_share < 40:
        barrier_score += 6
    else:
        barrier_score += 3

    # 新品机会越大，壁垒越小
    if low_review_share > 40:
        barrier_score += 10
    elif low_review_share > 20:
        barrier_score += 6
    else:
        barrier_score += 3

    scores['进入壁垒'] = barrier_score

    # 5. 利润空间 (15分)
    if avg_price > 300:
        scores['利润空间'] = 12
    elif avg_price > 150:
        scores['利润空间'] = 10
    elif avg_price > 50:
        scores['利润空间'] = 7
    else:
        scores['利润空间'] = 4

    # 计算总分
    scores['总分'] = sum(scores.values())

    # 评级
    if scores['总分'] >= 80:
        scores['评级'] = '优秀'
    elif scores['总分'] >= 70:
        scores['评级'] = '良好'
    elif scores['总分'] >= 50:
        scores['评级'] = '一般'
    else:
        scores['评级'] = '较差'

    return scores


def main():
    """命令行入口"""
    if len(sys.argv) < 2:
        print("用法: python extract_category_stats.py <响应文件路径>")
        print("\n示例:")
        print("  python extract_category_stats.py temp_response.txt")
        print("\n或者从标准输入读取:")
        print("  cat temp_response.txt | python extract_category_stats.py -")
        sys.exit(1)

    file_path = sys.argv[1]

    # 提取统计数据
    stats = extract_statistics(file_path)

    if not stats:
        print("未能提取到统计数据")
        sys.exit(1)

    print("=" * 60)
    print("类目统计数据")
    print("=" * 60)

    # 打印统计数据
    for name, value in stats.items():
        if value != "未找到":
            print(f"  {name}: {value}")

    # 计算评分
    scores = calculate_scores_from_stats(stats)

    print("\n" + "=" * 60)
    print("五维评分")
    print("=" * 60)

    for dimension, score in scores.items():
        if dimension not in ['总分', '评级']:
            print(f"  {dimension}: {score}")

    print(f"\n  总分: {scores['总分']}/100")
    print(f"  评级: {scores['评级']}")

    # 输出 JSON 格式 (便于脚本使用)
    if '--json' in sys.argv:
        output = {
            'statistics': stats,
            'scores': scores
        }
        print("\n" + "=" * 60)
        print("JSON 格式输出")
        print("=" * 60)
        print(json.dumps(output, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Sorftime 类目关键词解析器
处理 category_keywords 返回的 SSE 响应
"""

import re
import json
import codecs
import sys
import os


def fix_mojibake(obj):
    """
    修复 UTF-8/Latin-1 双重编码问题 (Mojibake)

    当 UTF-8 字节被错误地解释为 Latin-1 时会产生乱码:
    解决方法: encode('latin-1') → decode('utf-8')
    """
    if isinstance(obj, dict):
        return {fix_mojibake(k): fix_mojibake(v) for k, v in obj.items()}
    elif isinstance(obj, list):
        return [fix_mojibake(item) for item in obj]
    elif isinstance(obj, str):
        # 检查是否包含典型 Mojibake 模式
        mojibake_patterns = ['æ ', 'é¢', 'å ', 'ä»£', 'åç', 'å³']
        if any(p in obj for p in mojibake_patterns):
            try:
                return obj.encode('latin-1').decode('utf-8')
            except:
                return obj
        return obj
    else:
        return obj


def decode_keywords_response(file_path: str) -> list:
    """
    解码 category_keywords SSE 响应文件

    Args:
        file_path: SSE 响应文件路径

    Returns:
        list: 关键词数据列表
    """
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    # 方法 1: 查找 SSE data 行
    for line in content.split('\n'):
        if line.startswith('data: '):
            json_text = line[6:]
            try:
                data = json.loads(json_text)
                result_text = data.get('result', {}).get('content', [{}])[0].get('text', '')
                if result_text and ('关键词' in result_text or 'keyword' in result_text.lower()):
                    # 解码 Unicode 转义
                    decoded = codecs.decode(result_text, 'unicode-escape')

                    # 提取 JSON 数组 - 支持多种格式
                    # 格式 1: [{"关键词": 或格式 2: [{"keyword":
                    start = decoded.find('[{"关键词"')
                    if start == -1:
                        start = decoded.find('[{"keyword"')
                    if start == -1:
                        start = decoded.find('[{')

                    if start != -1:
                        # 找到匹配的结束括号
                        bracket_count = 0
                        in_string = False
                        escape_next = False
                        end = -1

                        for i in range(start, len(decoded)):
                            c = decoded[i]

                            if escape_next:
                                escape_next = False
                                continue

                            if c == '\\':
                                escape_next = True
                                continue

                            if c == '"' and not escape_next:
                                in_string = not in_string
                                continue

                            if not in_string:
                                if c == '[':
                                    bracket_count += 1
                                elif c == ']':
                                    bracket_count -= 1
                                    if bracket_count == 0:
                                        end = i + 1
                                        break

                        if end != -1:
                            json_str = decoded[start:end]
                            result = json.loads(json_str)
                            # 修复可能的编码问题
                            return fix_mojibake(result)
            except Exception as e:
                print(f"方法1解析失败: {e}")
                continue

    # 方法 2: 备用方法 - 直接从原始内容提取
    # 查找包含关键词的 JSON 数组片段
    bracket_count = 0
    in_array = False
    start = -1
    end = -1

    for i, c in enumerate(content):
        if c == '[':
            if not in_array:
                # 检查这是否是关键词数组的开始
                lookahead = content[i:i+200]
                if ('关键词' in lookahead or 'keyword' in lookahead.lower()):
                    in_array = True
                    start = i
            bracket_count += 1
        elif c == ']':
            bracket_count -= 1
            if in_array and bracket_count == 0:
                end = i + 1
                break

    if start != -1 and end != -1:
        raw_json = content[start:end]
        try:
            # 清理并解码
            decoded = codecs.decode(raw_json, 'unicode-escape')
            result = json.loads(decoded)
            return fix_mojibake(result)
        except Exception as e:
            print(f"方法2解析失败: {e}")

    # 方法 3: 使用正则表达式提取关键词数组
    try:
        # 查找 [{...}] 模式
        array_pattern = r'\[\{[^\]]*?"关键词"[^\]]*?\}'
        matches = re.findall(array_pattern, content, re.DOTALL)
        for match in matches:
            try:
                decoded = codecs.decode(match, 'unicode-escape')
                result = json.loads(decoded)
                if isinstance(result, list) and len(result) > 0:
                    return fix_mojibake(result)
            except:
                continue
    except Exception as e:
        print(f"方法3解析失败: {e}")

    raise ValueError("无法解析关键词数据 - 请检查文件格式是否正确")


def format_keyword_data(kw: dict) -> dict:
    """格式化单个关键词数据"""
    return {
        '关键词': kw.get('关键词', ''),
        '周搜索排名': kw.get('周搜索排名', '0'),
        '周搜索量': kw.get('周搜索量', '0'),
        '月搜索量': kw.get('月搜索量', '0'),
        'CPC竞价': kw.get('cpc精准竞价', '0'),
        '搜索结果数': kw.get('搜索结果数', '0'),
        '新品占比': kw.get('搜索结果前3页产品中上线3个月内产品数量占比', '0'),
    }


def print_keywords_table(keywords: list, limit: int = 20):
    """打印关键词表格"""
    print("\n" + "=" * 90)
    print(f"类目核心关键词 Top {min(len(keywords), limit)}")
    print("=" * 90)
    print(f"{'排名':<6}{'关键词':<25}{'月搜索量':<15}{'周排名':<10}{'CPC竞价':<10}{'新品占比':<10}")
    print("-" * 90)

    for i, kw in enumerate(keywords[:limit], 1):
        keyword = kw.get('关键词', 'N/A')
        monthly = kw.get('月搜索量', '0')
        rank = kw.get('周搜索排名', '0')
        cpc = kw.get('CPC竞价', '0')
        new_pct = kw.get('新品占比', '0')

        # 格式化数字
        try:
            monthly = f"{int(float(monthly)):,}"
        except:
            pass

        try:
            cpc = f"${float(cpc):.2f}"
        except:
            cpc = f"${cpc}"

        try:
            new_pct = f"{new_pct}%"
        except:
            pass

        print(f"{i:<6}{keyword:<25}{monthly:<15}{rank:<10}{cpc:<10}{new_pct:<10}")


def save_keywords(keywords: list, output_file: str):
    """保存关键词到文件"""
    with open(output_file, 'w', encoding='utf-8') as f:
        f.write("类目核心关键词\n")
        f.write("=" * 90 + "\n")
        f.write(f"{'排名':<6}{'关键词':<25}{'月搜索量':<15}{'周排名':<10}{'CPC竞价':<10}{'新品占比':<10}\n")
        f.write("-" * 90 + "\n")

        for i, kw in enumerate(keywords, 1):
            keyword = kw.get('关键词', 'N/A')
            monthly = kw.get('月搜索量', '0')
            rank = kw.get('周搜索排名', '0')
            cpc = kw.get('CPC竞价', '0')
            new_pct = kw.get('新品占比', '0')

            try:
                monthly = f"{int(float(monthly)):,}"
            except:
                pass
            try:
                cpc = f"${float(cpc):.2f}"
            except:
                pass
            try:
                new_pct = f"{new_pct}%"
            except:
                pass

            f.write(f"{i:<6}{keyword:<25}{monthly:<15}{rank:<10}{cpc:<10}{new_pct:<10}\n")


def main():
    if len(sys.argv) < 2:
        print("用法: python keywords_parser.py <SSE响应文件> [输出目录] [显示数量]")
        print("\n示例:")
        print("  python keywords_parser.py keywords_response.txt")
        print("  python keywords_parser.py keywords_response.txt ./output 50")
        sys.exit(1)

    file_path = sys.argv[1]
    output_dir = sys.argv[2] if len(sys.argv) > 2 else '.'
    limit = int(sys.argv[3]) if len(sys.argv) > 3 and sys.argv[3].isdigit() else 20

    try:
        # 解码关键词响应
        keywords_raw = decode_keywords_response(file_path)

        # 格式化数据
        keywords = [format_keyword_data(kw) for kw in keywords_raw]

        # 打印表格
        print_keywords_table(keywords, limit)

        # 保存到文件
        os.makedirs(output_dir, exist_ok=True)
        output_file = os.path.join(output_dir, 'keywords.txt')
        save_keywords(keywords, output_file)
        print(f"\n关键词已保存到: {output_file}")

        # 保存 JSON 格式
        json_file = os.path.join(output_dir, 'keywords.json')
        with open(json_file, 'w', encoding='utf-8') as f:
            json.dump(keywords, f, ensure_ascii=False, indent=2)
        print(f"JSON 格式已保存到: {json_file}")

    except Exception as e:
        print(f"错误: {e}")
        import traceback
        traceback.print_exc()
        sys.exit(1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Sorftime category_report 完整解析脚本
一键提取统计数据、产品列表、计算评分
"""

import re
import sys
import json
import codecs
from typing import Dict, List, Optional


class CategoryReportParser:
    """类目报告解析器"""

    def __init__(self, file_path: str):
        self.file_path = file_path
        self.content = None
        self.statistics = {}
        self.products = []
        self.scores = {}

    def load(self) -> bool:
        """加载文件"""
        try:
            with open(self.file_path, 'r', encoding='utf-8') as f:
                self.content = f.read()
            return True
        except Exception as e:
            print(f"错误: 无法读取文件 - {e}")
            return False

    def extract_statistics(self) -> Dict[str, str]:
        """提取统计数据"""
        if not self.content:
            return {}

        # 先解码 Unicode 转义
        decoded_content = self._decode_unicode_escapes(self.content)

        # 使用 Unicode 转义格式的键名（如 \u0022\u6807\u9898\u0022 = "标题"）
        # 以及普通格式的键名
        patterns = [
            # Unicode 转义格式
            (r'\\u0022top100\u4ea7\u54c1\u6708\u9500\u91cf\\u0022:\\u0022?(\d+)\\u0022?', '总销量'),
            (r'\\u0022top100\u4ea7\u54c1\u6708\u9500\u989d\\u0022:\\u0022?([\d.]+)\\u0022?', '总销额'),
            (r'\\u0022average_price\\u0022:\\u0022?([\d.]+)\\u0022?', '平均价格'),
            (r'\\u0022median_price\\u0022:\\u0022?([\d.]+)\\u0022?', '中位数价格'),
            (r'\\u0022top3_brands_sales_volume_share\\u0022:\\u0022?([\d.]+%?)\\u0022?', 'Top3品牌占比'),
            (r'\\u0022amazonOwned_sales_volume_share\\u0022:\\u0022?([\d.]+%?)\\u0022?', 'Amazon自营占比'),
            (r'\\u0022low_reviews_sales_volume_share\\u0022:\\u0022?([\d.]+%?)\\u0022?', '低评论占比'),
            # 普通格式（如果已解码）
            (r'"top100产品月销量":"?(\d+)"?', '总销量'),
            (r'"top100产品月销额":"?([\d.]+)"?', '总销额'),
            (r'"average_price":"?([\d.]+)"?', '平均价格'),
            (r'"top3_brands_sales_volume_share":"?([\d.]+%?)"?', 'Top3品牌占比'),
            (r'"amazonOwned_sales_volume_share":"?([\d.]+%?)"?', 'Amazon自营占比'),
            (r'"low_reviews_sales_volume_share":"?([\d.]+%?)"?', '低评论占比'),
        ]

        results = {}
        for pattern, name in patterns:
            match = re.search(pattern, decoded_content)
            if match:
                results[name] = match.group(1)
            elif name not in results:  # 只在第一次尝试未找到时记录
                results[name] = "未找到"

        self.statistics = results
        return results

    def _decode_unicode_escapes(self, text: str) -> str:
        """解码 Unicode 转义字符"""
        # 处理 SSE 格式
        decoded = text
        for line in decoded.split('\n'):
            if line.startswith('data: '):
                json_text = line[6:]
                try:
                    data = json.loads(json_text)
                    result_text = data.get('result', {}).get('content', [{}])[0].get('text', '')
                    if result_text:
                        # 解码 Unicode 转义
                        return codecs.decode(result_text, 'unicode-escape')
                except:
                    pass
        return decoded

    def extract_products(self, limit: int = 100) -> List[Dict]:
        """提取 Top N 产品"""
        if not self.content:
            return []

        # 先解码 Unicode 转义
        decoded_content = self._decode_unicode_escapes(self.content)

        products = []

        # Unicode 转义格式的键名
        # \u0022ASIN\u0022 = "ASIN", \u0022\u6807\u9898\u0022 = "标题", etc.
        # 匹配完整的产品对象
        product_pattern = r'\{\\u0022ASIN\\u0022:\\u0022([A-Z0-9]{10})\\u0022[^\}]*?\\u0022\u6708\u9500\u91cf\\u0022:\\u0022?(\d+)\\u0022?[^\}]*?\\u0022\u6807\u9898\\u0022:\\u0022([^\\u0022]{30,150})\\u0022[^\}]*?\\u0022\u4ef7\u683c\\u0022:([\d.]+)[^\}]*?\\u0022\u661f\u7ea7\\u0022:\\u0022?([\d.]+)\\u0022?[^\}]*?\\u0022\u54c1\u724c\\u0022:\\u0022([^\\u0022]+?)\\u0022[^\}]*?\}'

        for match in re.finditer(product_pattern, decoded_content):
            asin, sales, title, price, rating, brand = match.groups()

            products.append({
                'ASIN': asin,
                '标题': title,
                '价格': float(price),
                '月销量': int(sales),
                '评分': float(rating),
                '品牌': brand
            })

            if len(products) >= limit:
                break

        # 如果 Unicode 格式没找到，尝试普通格式
        if len(products) < limit:
            product_pattern2 = r'\{"ASIN":"([A-Z0-9]{10})"[^\}]*?"月销量":"?(\d+)"?[^\}]*?"标题":"([^"]{30,150})"[^\}]*?"价格":"?([\d.]+)"?[^\}]*?"星级":"?([\d.]+)"?[^\}]*?"品牌":"([^"]+?)"[^\}]*?\}'
            for match in re.finditer(product_pattern2, decoded_content):
                asin, sales, title, price, rating, brand = match.groups()
                # 避免重复添加
                if not any(p['ASIN'] == asin for p in products):
                    products.append({
                        'ASIN': asin,
                        '标题': title,
                        '价格': float(price),
                        '月销量': int(sales),
                        '评分': float(rating),
                        '品牌': brand
                    })
                    if len(products) >= limit:
                        break

        self.products = products
        return products

    def calculate_scores(self) -> Dict[str, float]:
        """计算五维评分"""
        if not self.statistics:
            return {}

        def safe_float(value, default=0):
            try:
                return float(str(value).replace('%', '').replace(',', ''))
            except:
                return default

        revenue = safe_float(self.statistics.get('总销额', 0))
